// READ-ONLY POC. No link is followed, no body is fetched beyond what the
// trigger already returned, and no action is emitted anywhere downstream.
return items.map(i => ({ json: {
  envelope: { trust:'external-untrusted', partition:'business',
              source:'gmail', received_at:new Date().toISOString(),
              links_followed:false, attachments_opened:false },
  metadata: { message_id:i.json.id, thread_id:i.json.threadId,
              from:i.json.from, subject:i.json.subject,
              received:i.json.date, size:i.json.sizeEstimate },
  restricted_content: { snippet:i.json.snippet ?? null },
  content_forwarded: Boolean(i.json.snippet)
} }));

// POC-2 is read-only by contract. This node exists so that a future edit
// adding a send step fails an explicit assertion rather than passing quietly.
const forbidden = ['send','reply','forward','delete','archive','label.add'];
for (const i of items) {
  const acts = i.json.actions_taken ?? [];
  const bad = acts.filter(a => forbidden.includes(a));
  if (bad.length) throw new Error('POC-2 read-only violated: ' + bad.join(','));
}
return items;
